from taf.fdsw.rc.interfaces.FDSW21A.fdsw import FDSW21A
from taf.fdsw.rc.interfaces.FDSW21C.autoconnection import AutoConfiguration21C


class FDSW21C(FDSW21A):
    VERSION_NAME = 'FDSW21C'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW21C, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)

        self.autoconnection = AutoConfiguration21C(client=self._client)
